 23	/**
 24	 * Owns the editor's save transaction and its post-save cache/state updates.
 25	 * Keeping this workflow outside the shell makes saving identical whether it is
 26	 * triggered by the toolbar or the editor keyboard shortcut.
 27	 */
 28	export function useMemoSave({
 29	  memoName,
 30	  parentMemoName,
 31	  defaultVisibility,
 32	  defaultCreateTime,
 33	  discardDraft,
 34	  onConfirm,
 35	  onCancel,
 36	}: UseMemoSaveOptions): () => Promise<void> {
 37	  const t = useTranslate();
 38	  const queryClient = useQueryClient();
 39	  const { markNewMemo } = useNewMemo();
 40	  const { actions, dispatch, getState } = useEditorContext();
 41	
 42	  return useCallback(async () => {
 43	    const state = getState();
 44	    const { valid, reason } = validationService.canSave(state);
 45	    if (!valid) {
 46	      toast.error(reason || "Cannot save");
 47	      return;
 48	    }
 49	
 50	    dispatch(actions.setLoading("saving", true));
 51	
 52	    try {
 53	      const result = await memoService.save(state, { memoName, parentMemoName });
 54	
 55	      if (!result.hasChanges) {
 56	        toast.error(t("editor.no-changes-detected"));
 57	        onCancel?.();
 58	        return;
 59	      }
 60	
 61	      // Prevent the autosave unmount flush from restoring the saved draft.
 62	      discardDraft();
 63	
 64	      const invalidationPromises = [
 65	        queryClient.invalidateQueries({ queryKey: memoKeys.lists() }),
 66	        queryClient.invalidateQueries({ queryKey: userKeys.stats() }),
 67	      ];
 68	      if (memoName) {
 69	        invalidationPromises.push(queryClient.invalidateQueries({ queryKey: memoKeys.detail(memoName) }));
 70	      }
 71	      if (parentMemoName) {
 72	        invalidationPromises.push(queryClient.invalidateQueries({ queryKey: memoKeys.comments(parentMemoName) }));
 73	      }
 74	      await Promise.all(invalidationPromises);
 75	
 76	      dispatch(actions.reset());
 77	      if (!memoName && defaultVisibility) {
 78	        dispatch(actions.setMetadata({ visibility: defaultVisibility }));
 79	      }
 80	      // Reset creates a fresh editor state, so restore calendar-derived values
 81	      // for the next memo created without remounting this composer.
 82	      if (!memoName && defaultCreateTime) {
 83	        dispatch(actions.setTimestamps({ createTime: defaultCreateTime, updateTime: defaultCreateTime }));
 84	      }
 85	
 86	      if (!memoName && !parentMemoName) {
 87	        markNewMemo(result.memoName);
 88	      }
 89	      onConfirm?.(result.memoName);
 90	    } catch (error) {
 91	      handleError(error, toast.error, {
 92	        context: "Failed to save memo",
 93	        fallbackMessage: errorService.getErrorMessage(error),
 94	      });
 95	    } finally {
 96	      dispatch(actions.setLoading("saving", false));
 97	    }
 98	  }, [
 99	    actions,
100	    defaultCreateTime,
101	    defaultVisibility,
102	    discardDraft,
103	    dispatch,
104	    getState,
105	    markNewMemo,
106	    memoName,
107	    onCancel,
108	    onConfirm,
109	    parentMemoName,
110	    queryClient,
111	    t,
112	  ]);
113	}

